def priority(item: float, bins: np.ndarray) -> np.ndarray:
    target_fill = 0.85
    remaining = bins - item
    post_fill = 1.0 - (remaining / bins)
    return np.where((bins < item) | (bins <= 0), -np.inf, -np.square(post_fill - target_fill))

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    utilization = 1.0 - (remaining / bins)
    score = np.exp(-((utilization - 0.85) ** 2) / 0.02)
    return np.where((bins < item) | (bins <= 0) | (utilization > 0.98), -np.inf, score)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    optimal_remaining = 0.2 * bins
    score = -((remaining - optimal_remaining) ** 2) / (bins + 1e-8)
    return np.where((bins < item) | (bins <= 0), -np.inf, score)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    fill_ratio = item / (bins + 1e-8)
    optimal_ratio = 0.8
    score = -np.abs(fill_ratio - optimal_ratio) - np.maximum(0, fill_ratio - 1.0) * 1000
    return np.where((bins < item) | (bins <= 0), -np.inf, score)
